import java.io.*;

public class Main {
    static List<String> connectivity(int n, int[][] edges, List<int[]> ops) {
        // edges[i] = {u, v} is edge number i + 1
        // ops.get(j) = {1, i} deletes edge i, or {2, u, v} asks whether u and v are connected
        // Return one "YES" / "NO" per query operation, in order
        // Write your solution here
        return new ArrayList<>();
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        in.nextToken();
        int q = (int) in.nval;
        int[][] edges = new int[m][2];
        for (int i = 0; i < m; i++) {
            in.nextToken(); edges[i][0] = (int) in.nval;
            in.nextToken(); edges[i][1] = (int) in.nval;
        }
        List<int[]> ops = new ArrayList<>();
        for (int j = 0; j < q; j++) {
            in.nextToken();
            int t = (int) in.nval;
            if (t == 1) {
                in.nextToken();
                ops.add(new int[]{1, (int) in.nval});
            } else {
                in.nextToken();
                int u = (int) in.nval;
                in.nextToken();
                int v = (int) in.nval;
                ops.add(new int[]{2, u, v});
            }
        }
        List<String> res = connectivity(n, edges, ops);
        StringBuilder sb = new StringBuilder();
        for (String s : res) sb.append(s).append("\n");
        System.out.print(sb);
    }
}
